body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 32px; }
h2 { font-size: 20px; }

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.cart-count {
  background-color: #2563eb;
  color: #ffffff;
  border-radius: 999px;
  padding: 2px 10px;
}

.search {
  width: 100%;
  padding: 10px 12px;
  margin: 12px 0;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  font-size: 16px;
  background-color: #ffffff;
  color: #18181b;
}

.product-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 768px) {
  .product-grid { grid-template-columns: 1fr 1fr 1fr; }
}

.product-card {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
}

.btn-add {
  background-color: #2563eb;
  color: #ffffff;
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 15px;
}

.btn-add:disabled {
  background-color: #a1a1aa;
  cursor: not-allowed;
}

.cart ul {
  list-style: none;
  padding: 0;
}

.cart li {
  padding: 6px 0;
  border-bottom: 1px solid #e4e4e7;
}

.cart-total {
  font-size: 20px;
  font-weight: 700;
  text-align: right;
}

.order-form {
  display: grid;
  gap: 12px;
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
  margin-top: 24px;
}

.order-form label {
  display: grid;
  gap: 4px;
  font-size: 14px;
}

.order-form input {
  padding: 10px 12px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  font-size: 16px;
  background-color: #ffffff;
  color: #18181b;
}

.field-error {
  color: #b91c1c;
  font-size: 13px;
  margin: 0;
}

.order-echo,
.confirmation {
  background-color: #ecfdf5;
  border: 1px solid #a7f3d0;
  border-radius: 10px;
  padding: 16px;
  margin-top: 16px;
}

.muted { color: #52525b; font-size: 14px; }

import React, { useState } from "react";
import { createRoot } from "react-dom/client";

const products = [
  { id: 1, name: "Монгол дээл", price: 129000 },
  { id: 2, name: "Малгай", price: 45000 },
  { id: 3, name: "Гутал", price: 89000 },
];

function formatPrice(value) {
  return "₮ " + value.toLocaleString("en-US");
}

function ProductCard({ name, price, onAdd }) {
  return (
    <article className="product-card">
      <h3>{name}</h3>
      <p className="price">{formatPrice(price)}</p>
      <button className="btn-add" data-testid="add-to-cart" onClick={onAdd}>
        Сагсанд хийх
      </button>
    </article>
  );
}

function CartList({ items }) {
  if (items.length === 0) {
    return <p data-testid="cart-empty">Сагс хоосон байна.</p>;
  }

  return (
    <ul data-testid="cart-items">
      {items.map((item) => (
        <li key={item.id}>
          {item.name} × {item.quantity}
        </li>
      ))}
    </ul>
  );
}

function OrderForm({ onSubmit }) {
  const [values, setValues] = useState({ name: "", phone: "", address: "" });

  // энд бичнэ үү

  function handleChange(event) {
    const { name, value } = event.target;
    setValues((prev) => ({ ...prev, [name]: value }));
  }

  function handleSubmit(event) {
    event.preventDefault();
    onSubmit(values);
  }

  return (
    <form className="order-form" data-testid="order-form" onSubmit={handleSubmit}>
      <h2>Захиалга өгөх</h2>
      <label>
        Нэр
        <input type="text"
          name="name"
          data-testid="f-name"
          value={values.name}
          onChange={handleChange}
        />
      </label>
      <label>
        Утас
        <input type="tel"
          name="phone"
          data-testid="f-phone"
          value={values.phone}
          onChange={handleChange}
        />
      </label>
      <label>
        Хаяг
        <input type="text"
          name="address"
          data-testid="f-address"
          value={values.address}
          onChange={handleChange}
        />
      </label>
      <button type="submit" className="btn-add" data-testid="f-submit">
        Захиалах
      </button>
    </form>
  );
}

function App() {
  const [cart, setCart] = useState([]);
  const [query, setQuery] = useState("");
  const [order, setOrder] = useState(null);

  function addToCart(product) {
    setCart((prev) => {
      const existing = prev.find((item) => item.id === product.id);
      if (existing) {
        return prev.map((item) =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  }

  const count = cart.reduce((sum, item) => sum + item.quantity, 0);
  const totalPrice = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

  const visible = products.filter((product) =>
    product.name.toLowerCase().includes(query.trim().toLowerCase())
  );

  return (
    <main>
      <header className="topbar">
        <h1>Shop.mn</h1>
        <span className="cart-count" data-testid="cart-count">{count}</span>
      </header>

      <input
        type="search"
        className="search"
        data-testid="search"
        placeholder="Бараа хайх…"
        aria-label="Бараа хайх"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
      />

      <section className="product-grid">
        {visible.map((product) => (
          <ProductCard
            key={product.id}
            name={product.name}
            price={product.price}
            onAdd={() => addToCart(product)}
          />
        ))}
      </section>

      <section className="cart">
        <h2>Сагс</h2>
        <CartList items={cart} />
        <p className="cart-total" data-testid="cart-total">{formatPrice(totalPrice)}</p>
      </section>
      <OrderForm onSubmit={setOrder} />
      {order ? (
        <p className="order-echo" data-testid="order-echo">Баярлалаа, {order.name}!</p>
      ) : null}
    </main>
  );
}

createRoot(document.getElementById("root")).render(<App />);

