import React, { useState } from "react";
import { createRoot } from "react-dom/client";

const products = [
  { id: 1, name: "Монгол дээл", price: 129000 },
  { id: 2, name: "Малгай", price: 45000 },
  { id: 3, name: "Гутал", price: 89000 },
];

function formatPrice(value) {
  return "₮ " + value.toLocaleString("en-US");
}

function validate(values) {
  const errors = {};

  if (values.name.trim().length < 2) {
    errors.name = "Нэрээ бичнэ үү.";
  }

  if (!/^\d{8}$/.test(values.phone.trim())) {
    errors.phone = "Утасны дугаар 8 оронтой байх ёстой.";
  }

  if (values.address.trim().length < 5) {
    errors.address = "Хаягаа бүтнээр нь бичнэ үү.";
  }

  return errors;
}

function ProductCard({ name, price, onAdd }) {
  return (
    <article className="product-card">
      <h3>{name}</h3>
      <p className="price">{formatPrice(price)}</p>
      <button className="btn-add" data-testid="add-to-cart" onClick={onAdd}>
        Сагсанд хийх
      </button>
    </article>
  );
}

function CartList({ items }) {
  if (items.length === 0) {
    return <p data-testid="cart-empty">Сагс хоосон байна.</p>;
  }

  return (
    <ul data-testid="cart-items">
      {items.map((item) => (
        <li key={item.id}>
          {item.name} × {item.quantity}
        </li>
      ))}
    </ul>
  );
}

function OrderForm({ onSubmit }) {
  const [values, setValues] = useState({ name: "", phone: "", address: "" });

  const errors = validate(values);
  const isValid = Object.keys(errors).length === 0;

  function handleChange(event) {
    const { name, value } = event.target;
    setValues((prev) => ({ ...prev, [name]: value }));
  }

  function handleSubmit(event) {
    event.preventDefault();
    if (!isValid) return;
    onSubmit(values);
  }

  return (
    <form className="order-form" data-testid="order-form" onSubmit={handleSubmit}>
      <h2>Захиалга өгөх</h2>
      <label>
        Нэр
        <input type="text"
          name="name"
          data-testid="f-name"
          value={values.name}
          onChange={handleChange}
        />
      </label>
      {errors.name ? (
        <p className="field-error" data-testid="err-name">{errors.name}</p>
      ) : null}
      <label>
        Утас
        <input type="tel"
          name="phone"
          data-testid="f-phone"
          value={values.phone}
          onChange={handleChange}
        />
      </label>
      {errors.phone ? (
        <p className="field-error" data-testid="err-phone">{errors.phone}</p>
      ) : null}
      <label>
        Хаяг
        <input type="text"
          name="address"
          data-testid="f-address"
          value={values.address}
          onChange={handleChange}
        />
      </label>
      {errors.address ? (
        <p className="field-error" data-testid="err-address">{errors.address}</p>
      ) : null}
      <button type="submit" className="btn-add" data-testid="f-submit" disabled={!isValid}>
        Захиалах
      </button>
    </form>
  );
}

function App() {
  const [cart, setCart] = useState([]);
  const [query, setQuery] = useState("");
  const [order, setOrder] = useState(null);

  function addToCart(product) {
    setCart((prev) => {
      const existing = prev.find((item) => item.id === product.id);
      if (existing) {
        return prev.map((item) =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  }

  const count = cart.reduce((sum, item) => sum + item.quantity, 0);
  const totalPrice = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

  const visible = products.filter((product) =>
    product.name.toLowerCase().includes(query.trim().toLowerCase())
  );

  return (
    <main>
      <header className="topbar">
        <h1>Shop.mn</h1>
        <span className="cart-count" data-testid="cart-count">{count}</span>
      </header>

      <input
        type="search"
        className="search"
        data-testid="search"
        placeholder="Бараа хайх…"
        aria-label="Бараа хайх"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
      />

      <section className="product-grid">
        {visible.map((product) => (
          <ProductCard
            key={product.id}
            name={product.name}
            price={product.price}
            onAdd={() => addToCart(product)}
          />
        ))}
      </section>

      <section className="cart">
        <h2>Сагс</h2>
        <CartList items={cart} />
        <p className="cart-total" data-testid="cart-total">{formatPrice(totalPrice)}</p>
      </section>
      <OrderForm onSubmit={setOrder} />
      {order ? (
        <p className="order-echo" data-testid="order-echo">Баярлалаа, {order.name}!</p>
      ) : null}
    </main>
  );
}

createRoot(document.getElementById("root")).render(<App />);
